package vn.covie.shipping.application;

import java.util.List; import java.util.UUID;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import vn.covie.merchants.model.MerchantLocationEntity; import vn.covie.merchants.persistence.MerchantLocationRepository; import vn.covie.merchants.security.*;
import vn.covie.shipping.api.dto.*; import vn.covie.shipping.model.*; import vn.covie.shipping.persistence.*; import vn.covie.shared.concurrency.VersionPrecondition; import vn.covie.shared.id.UuidV7Generator; import vn.covie.shared.time.AppClock; import vn.covie.shared.web.*;

@Service public class ShippingPolicyService {
    private final MerchantAccessPolicy access; private final MerchantLocationRepository locations; private final ShippingPolicyRepository policies; private final ShippingRuleRepository rules; private final UuidV7Generator ids; private final AppClock clock;
    public ShippingPolicyService(MerchantAccessPolicy access, MerchantLocationRepository locations, ShippingPolicyRepository policies, ShippingRuleRepository rules, UuidV7Generator ids, AppClock clock){this.access=access;this.locations=locations;this.policies=policies;this.rules=rules;this.ids=ids;this.clock=clock;}
    @Transactional(readOnly=true) public List<ShippingPolicyResponse> list(UUID merchantId,UUID locationId){requireLocation(merchantId,locationId);return policies.findByMerchantLocationIdOrderById(locationId).stream().map(this::response).toList();}
    @Transactional public ShippingPolicyResponse create(UUID merchantId,UUID locationId,ShippingPolicyUpsertRequest req){MerchantLocationEntity loc=requireLocation(merchantId,locationId); validate(loc,req); ShippingPolicyStatus st=req.status()==null?ShippingPolicyStatus.ACTIVE:req.status(); if(st==ShippingPolicyStatus.ACTIVE&&policies.findFirstByMerchantLocationIdAndPolicyStatus(locationId,ShippingPolicyStatus.ACTIVE).isPresent())throw err(ErrorCode.SHIPPING_POLICY_DUPLICATE_ACTIVE,HttpStatus.CONFLICT,"An active policy already exists."); ShippingPolicyEntity p=policies.saveAndFlush(ShippingPolicyEntity.create(ids.generate(),locationId,req.mode(),req.baseFee(),currency(req,loc),req.ruleMatchMode(),st,clock.now())); replaceRules(p.getId(),req.rules()); return response(p);}
    @Transactional public ShippingPolicyResponse update(UUID merchantId,UUID locationId,UUID policyId,String ifMatch,ShippingPolicyUpsertRequest req){MerchantLocationEntity loc=requireLocation(merchantId,locationId); ShippingPolicyEntity p=policies.findForUpdate(policyId,locationId).orElseThrow(ShippingPolicyService::notFound); VersionPrecondition.require(VersionPrecondition.parseRequired(ifMatch),p.getVersion()); validate(loc,req); ShippingPolicyStatus st=req.status()==null?p.getPolicyStatus():req.status(); if(st==ShippingPolicyStatus.ACTIVE&&p.getPolicyStatus()!=ShippingPolicyStatus.ACTIVE&&policies.findFirstByMerchantLocationIdAndPolicyStatus(locationId,ShippingPolicyStatus.ACTIVE).isPresent())throw err(ErrorCode.SHIPPING_POLICY_DUPLICATE_ACTIVE,HttpStatus.CONFLICT,"An active policy already exists."); p.update(req.mode(),req.baseFee(),currency(req,loc),req.ruleMatchMode(),st,clock.now()); ShippingPolicyEntity saved=policies.saveAndFlush(p); replaceRules(saved.getId(),req.rules()); return response(saved);}
    @Transactional public void delete(UUID merchantId,UUID locationId,UUID policyId,String ifMatch){requireLocation(merchantId,locationId); ShippingPolicyEntity p=policies.findForUpdate(policyId,locationId).orElseThrow(ShippingPolicyService::notFound); VersionPrecondition.require(VersionPrecondition.parseRequired(ifMatch),p.getVersion()); p.update(p.getMode(),p.getBaseFee(),p.getCurrencyCode(),p.getRuleMatchMode(),ShippingPolicyStatus.INACTIVE,clock.now()); policies.save(p);}
    private MerchantLocationEntity requireLocation(UUID merchantId,UUID locationId){access.requireLocation(merchantId,locationId,MerchantCapability.MANAGE_LOCATION_OFFER);return locations.findActiveForUpdate(locationId,merchantId).orElseThrow(ShippingPolicyService::notFound);}
    private String currency(ShippingPolicyUpsertRequest req,MerchantLocationEntity loc){String c=req.currencyCode()==null?loc.getCurrencyCode():req.currencyCode().strip().toUpperCase();if(!c.matches("[A-Z]{3}"))throw invalid("Currency code must be ISO-4217.");return c;}
    private void validate(MerchantLocationEntity loc,ShippingPolicyUpsertRequest req){if(req==null||req.mode()==null)throw invalid("Shipping mode is required.");if(req.baseFee()!=null&&req.baseFee()<0)throw invalid("Base fee must be non-negative.");List<ShippingRuleRequest> rs=req.rules()==null?List.of():req.rules();switch(req.mode()){case FREE,NEGOTIATED-> {if(req.baseFee()!=null||req.ruleMatchMode()!=null||!rs.isEmpty())throw invalid("Mode does not accept fee or rules.");}case FIXED->{if(req.baseFee()==null||req.ruleMatchMode()!=null||!rs.isEmpty())throw invalid("Fixed mode requires only a base fee.");}case CONDITIONAL->{if(req.baseFee()==null||req.ruleMatchMode()==null||rs.isEmpty())throw invalid("Conditional mode requires fee, match mode and rules.");validateRules(rs);}}}
    private void validateRules(List<ShippingRuleRequest> rs){java.util.Set<Integer> seen=new java.util.HashSet<>();for(var r:rs){if(r==null||r.conditionType()==null||r.operator()==null||r.actionType()!=ShippingActionType.FREE_SHIPPING||r.thresholdValue()<0||r.priority()<0||!seen.add(r.priority()))throw err(ErrorCode.SHIPPING_RULE_INVALID,HttpStatus.UNPROCESSABLE_ENTITY,"Invalid shipping rule.");if((r.conditionType()==ShippingConditionType.ORDER_AMOUNT_MIN&&r.operator()!=ShippingConditionOperator.GTE)||(r.conditionType()==ShippingConditionType.DISTANCE_MAX&&r.operator()!=ShippingConditionOperator.LTE))throw err(ErrorCode.SHIPPING_RULE_INVALID,HttpStatus.UNPROCESSABLE_ENTITY,"Invalid operator for condition.");}}
    private void replaceRules(UUID id,List<ShippingRuleRequest> rs){rules.deleteByShippingPolicyId(id);if(rs!=null&&!rs.isEmpty())rules.saveAll(rs.stream().map(r->ShippingRuleEntity.create(ids.generate(),id,r.conditionType(),r.operator(),r.thresholdValue(),r.actionType(),r.priority(),r.enabled())).toList());}
    private ShippingPolicyResponse response(ShippingPolicyEntity p){List<ShippingRuleRequest> rs=rules.findByShippingPolicyIdOrderByPriority(p.getId()).stream().map(r->new ShippingRuleRequest(r.getConditionType(),r.getOperator(),r.getThresholdValue(),r.getActionType(),r.getPriority(),r.isEnabled())).toList();return new ShippingPolicyResponse(p.getId(),p.getMerchantLocationId(),p.getMode(),p.getBaseFee(),p.getCurrencyCode(),p.getRuleMatchMode(),p.getPolicyStatus(),p.getVersion(),rs);}
    private static ApiException invalid(String m){return err(ErrorCode.SHIPPING_POLICY_INVALID,HttpStatus.UNPROCESSABLE_ENTITY,m);} private static ApiException notFound(){return new ApiException(ErrorCode.RESOURCE_NOT_FOUND,HttpStatus.NOT_FOUND,"Resource not found.");} private static ApiException err(ErrorCode c,HttpStatus s,String m){return new ApiException(c,s,m);}
}
